L["queue if switched on: %d"] = "в очереди, если включить: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "команды |cffffd100/manners %s|r нет -- может быть, вы имели в виду |cffffd100/manners %s|r? |cffffd100/manners help|r покажет их все."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "команды |cffffd100/manners %s|r нет -- может быть, вы имели в виду |cffffd100/manners %s|r? |cffffd100/manners dev|r покажет инструменты для проверки."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "Спасибо, {name}! Как вернемся в Стальгорн, первая кружка за мной!"
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Благодарствую, {name}. Теперь у тебя есть друг в горах."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "Спасибо, {name}! Не больно-то и надо было, заметь. Но спасибо."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "Ох, {name}, так бы и обнять! Да потом лекаря звать придется."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "Уже в расчете, {name}! Мой счет в таверне такой прыти не видал."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "В Караносе расскажу, будто мне жизнь спасли, {name}. Спасибо!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "Славно, {name}! Статую бы тебе высечь, да так быстрее."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "Титаны вытесали нас из камня, {name}, но и камень растрогался. Спасибо."
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "Ага, {name}, стоило лишь попросить! Замри, как добрая наковальня."
L["Say no more, {name}. Stone and steel, here it comes."] = "Ни слова больше, {name}. Во имя камня и стали, держи!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "Попроси дворфа о помощи, {name}, -- и получишь. Громко."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "Ну, {name}, держись: я все делаю так, будто молотом машу."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "Ага, {name}, и байка в придачу, хоть никто не просил. С чего начать..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "Наливаю, {name}: {buff}! Прямо из бочки, с пеной."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "Готово, {name}. Работа дворфов: на века, задешево и с гарантией."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "На-ка, {name}, чтоб ноги держали. Мал золотник, да дорог!"
L["Off ye go, {name}, steady as the mountain."] = "Ступай, {name}, да стой крепко, что твоя гора."
L["Here, {name}. Ale's for after; this is for before."] = "Держи, {name}. Эль -- после боя, а это -- до."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "Магни ради общего дела стал алмазом, {name}. Это вариант подешевле."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "Дворф прикроет спину, {name}. Ну, колени. Почти то же самое."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "Пристанет трогг, {name}, -- скажи, что тебя дворф прислал. И беги."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "Если выдохнется, {name}, стукни хорошенько. Мы так все чиним."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "Держи, {name}. Упрямства бы тоже отсыпать, но мое все при деле."
L["Stone and hammer keep ye, cousin {name}!"] = "Да хранят тебя камень и молот, {name}, родная кровь!"
L["Three Hammers, one round, cousin {name}!"] = "Три молота, одна бочка, {name}, родня!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "Спорим, {name}, наши родичи давно переженились? Гора тесна."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "Два дворфа вместе, {name}. Жаль того, кто встанет у нас на пути."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "Встань за мной, {name}. Да, знаю. Пригнись чуток."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "Значит так, {name}: я -- в лоб, ты -- за добычей, а спорим потом."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "Если я запою, {name}, значит, бой идет хорошо. Или совсем плохо."
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "Дворфы своих не бросают, {name}. И бочонки тоже. Но своих -- первыми."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "Бороды вперед, {name}! Безбородым -- смотреть грозно. Почти не хуже."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "Утро доброе, {name}! Для эля рановато. Почти. Сперва вот это."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "Горны уже горят, {name}! Утро дворфа -- это молот и вот это."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "Рано, {name}? Ерунда. Шахта уже два часа как открыта. Держи."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "Благодарю, {name}. Позволь ответить, пока барды все не переврали."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Любезно с твоей стороны, {name}. Мы друзей не забываем."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "Спасибо, {name}. В рыцари бы тебя посвятить, да «нужно разрешение»."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "Возвращаю сразу, {name}. В Штормграде нужны были бы три справки и печать."
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "Спасибо, {name}. Заплатить бы золотом, но Штормград еще каменщикам должен."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "Спасибо, {name}. Мама учила: добро надо возвращать. И тарелку тоже."
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "Спасибо, {name}. Долг погашен, по королевскому указу. Моему."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "Какой стыд, {name}, мне следовало додуматься раньше. Позволь."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "Конечно, {name}. Замри и прими героическую позу, бардам так легче."
L["Right away, {name}. Keep your shield high."] = "Сию минуту, {name}. Держи щит выше."
L["More work? Gladly, {name}. It beats the lumber mill."] = "Еще работа? Охотно, {name}. Всяко лучше лесопилки."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "Конечно, {name}. Люди мастера помогать и обещать с три короба. Это -- помощь."
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "Разумеется, {name}. Люди быстро учатся: я это знаю аж со вчерашнего дня."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "Замри, {name}, как статуя на Аллее Героев. Тебе там самое место."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "Сию минуту, {name}. Свет помогает просящим. Я тоже, только быстрее."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "Впереди долгий путь, {name}. Короче он не станет, но идти будет легче."
L["Fair winds and following seas, {name}."] = "Попутного ветра и семь футов под килем, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "Держи, {name}. У эльфов века на щедрость, а у меня лет пятьдесят."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "Небольшой подарок, {name}. Стражникам ни слова, а то все захотят."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "Держи, {name}. Если кобольд спросит -- свечки у тебя нет."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "Держи, {name}. Людской подарок: от души, наспех и на удивление прочный."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "Берегись мурлоков, {name}. Держи: знаю, что они творят с пикниками."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "Каждой дороге нужен герой, {name}. Сегодня, похоже, это я. Держи."
L["Arathor's children stand together, {name}."] = "Дети Аратора держатся вместе, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "Еще один человек, {name}! Скорее, оснуем королевство до обеда."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "Штормград или Боралус, {name}, а на погоду жалуемся одинаково."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "Как человек человеку, {name}: нет, я тоже не знаю, почему все шишки на нас."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "Держись рядом, {name}. Люди побеждают не умением, а числом."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "Держи строй, {name}. Строя у нас нет, но ты все равно держи."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "Составлю план, {name}, а потом дружно его проигнорируем."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "У каждого героя из песен были друзья, {name}. О них не поют. А я спою."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "Щиты выше, {name}. В Штормграде учат маршировать, а останавливаться -- нет."
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ишну-ала, {name}. Возвращаю в тот же день -- для калдорай это спешка."
L["Thank you, {name}. Elune smiles on the generous."] = "Спасибо, {name}. Элуна благоволит щедрым."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "Спасибо, {name}. Даже огоньки засияли ярче, а их удивить непросто."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "Элуна это видела, {name}. Она видит все, так что лучше вернуть."
L["Thank you, {name}. Returned before I nap for a century or two."] = "Спасибо, {name}. Возвращаю до следующей спячки на век-другой."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "Спасибо, {name}. Древние об этом узнают. Они жуткие сплетники."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "Спасибо, {name}. Скажу Часовым, чтобы в тебя больше не целились."
L["My people never hurry, {name}. For you, an exception."] = "Мой народ не спешит, {name}. Для тебя -- исключение."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "С радостью, {name}. Замри, и пусть тебя коснется лунный свет."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Конечно, {name}. Благословением Элуны нужно делиться."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "Наконец-то, {name}! Десять тысяч лет жду, когда кто-нибудь попросит."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "Без загадок и знамений Элуны, {name}. Просто «да», для разнообразия."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "Конечно, {name}. Попроси по-дарнасски -- добавлю поклон."
L["Elune already said yes, {name}. I'm merely catching up."] = "Элуна уже сказала «да», {name}. Я лишь догоняю."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "Конечно, {name}. Замри и представь, что ты дерево. Помогает."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Элун-адоре, {name}. Ступай тише: у деревьев чуткий сон."
L["May the forest shelter you, {name}, wherever you roam."] = "Да укроет тебя лес, {name}, куда бы ни вел твой путь."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "Дар из теней, {name}. Нет, не оглядывайся. Меня не найти."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "Элуна освещает твой путь, {name}. Я лишь держу фонарь."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "Совы указали на тебя, {name}. У них на все свое мнение. Держи."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "Тиранда бы настояла, {name}, а с Тирандой не спорят."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "Держи, {name}. До тебя это получил гиппогриф. Спасибо не сказал."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "Осторожнее со зверьем, {name}. Половина -- друиды, и все за тобой следят."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ишну-ала, {name}. Элуна бережет своих детей."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "Конечно, я тебя вижу, {name}. Калдорай калдорай видит издалека."
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "Как калдорай калдорай, {name}: Древо мы потеряли, но не друг друга."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "Калдорай не бросит родню во тьме, {name}. Разве что ради укрытия."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "Быстренько, {name}? По меркам калдорай мы закончим, не начав."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "Меня не будет видно, {name}. Это не ошибка, это план."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "Элуна присматривает за всей группой, {name}. А я ей машу."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "За десять тысяч лет было много спутников, {name}. Вы -- из лучших."
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "Держись рядом, {name}. Два Мировых Древа мы потеряли. Тебя -- не потеряем."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "Луна взошла, {name}. Для калдорай это разгар утра."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "Все разумные уже спят, {name}. Нам с Элуной так больше нравится."
L["Moonlight suits you, {name}. This is merely a second layer."] = "Тебе к лицу лунный свет, {name}. А это -- лишь второй слой."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "Утро, {name}. Мой народ тысячелетиями его просыпал. Привыкаю."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "Рассвет, {name}. Элуна ушла спать, так что я за нее."
L["The sun's up, {name}, and so, reluctantly, am I."] = "Солнце встало, {name}, а с ним, скрепя сердце, и я."
L["The shadows remember kindness, {name}. So do I."] = "Тени помнят доброту, {name}. Как и я."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Благодарю, {name}. Рен'дорай не забывают добра."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "Спасибо, {name}. Голоса тебя одобряют, и это, честно говоря, тревожно."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "Спасибо, {name}. Редко кто дарит что-то тому, кто так зловеще светится."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "Доброта в Бездне редкость, {name}. Верну твою, пока Бездна не заметила."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "Луносвет нас выгнал, {name}. С такими, как ты, и обижаться трудно."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "Возвращаю сполна, {name}. Слегка отдает фиолетовым -- это нормально."
L["The Void only takes, {name}. I, however, give back."] = "Бездна только берет, {name}. А я возвращаю."
L["As you wish, {name}. The shadows answer kindly today."] = "Как пожелаешь, {name}. Сегодня тени благосклонны."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "Считай, что сделано, {name}. Бездна служит нам, а не наоборот."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "Конечно, {name}. Голоса шепнули «нет», значит, точно «да»."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "Конечно, {name}. {buff} -- со щепоткой Бездны."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "Конечно, {name}. Замри: тени стесняются незнакомцев."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "Охотно, {name}. Манеры рен'дорай: Бездна ждет своей очереди."
L["Asked so nicely, {name}? The Void never says please. Here."] = "Как вежливо, {name}! Бездна «пожалуйста» не говорит. Держи."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Щепотка тьмы для тебя, {name}. Вполне безопасно. Почти."
L["Walk carefully in the dark places, {name}."] = "Во тьме ступай осторожно, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "Гостинец из Разлома Телогрус, {name}. Там чище, чем звучит."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "Держи, {name}. Щупальца, если что, чисто декоративные."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "Тени о тебе спрашивают, {name}. Я им напоминаю о манерах."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "Держи, {name}. Мы шагнули в Бездну, чтобы тебе не пришлось."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "Твоя тень проверена, {name}. Никто не прячется. Но держи на всякий."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "Умбрик передает привет, {name}. Не передает, но передал бы."
L["We ren'dorei look after our own, {name}."] = "Мы, рен'дорай, своих не бросаем, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "Луносвет много потерял, {name}. А нам без него прекрасно."
L["Your whispers and mine should really meet sometime, {name}."] = "Твоим голосам и моим пора бы познакомиться, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "Двое рен'дорай, {name}! Живо, напусти мрачности -- от нас этого ждут."
L["Stay close, {name}. The whispers are much quieter in company."] = "Держись рядом, {name}. В компании шепот куда тише."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "Если тени начнут командовать, {name}, не слушай. Я обычно не слушаю."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "Присмотри за моей тенью, {name}. В бою она любит сбегать."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "Если я засвечусь фиолетовым, {name}, не пугайся. Это от усердия."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "С рен'дорай в пути хорошо, {name}: свою тьму для пряток носим с собой."
L["Night suits the ren'dorei, {name}. We match the decor."] = "Ночь к лицу рен'дорай, {name}. Мы в тон обстановке."
L["The shadows are longest now, {name}, and in a very generous mood."] = "Сейчас тени длиннее всего, {name}, и очень щедры."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "Поздно, {name}? Голоса любят поздний час. С недавних пор -- и я."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "Спасибо, {name}! Доброта получена, занесена в реестр и возвращена!"
L["Reciprocity engaged! Much obliged, {name}."] = "Режим взаимности включен! Спасибо, {name}."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "По расчетам, {name}, с меня ровно одна штука: {buff}."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "Спасибо, {name}! Собрать бы тебе машину благодарности, да взорвется."
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "Спасибо, {name}! Это надо отметить. Отойди, сейчас сконструирую праздник."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "Какая доброта, {name}! На ответ ушло всего четыре чертежа."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "Вот досада, {name}! Благодарность была в чертежах, но меня опередили."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "Ох, {name}, как мило! У меня опять сердце зажужжало."
L["Request received, {name}! Processing... done!"] = "Запрос принят, {name}! Обработка... готово!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "Улучшение уже в пути, {name}! Не шевелись, идет калибровка."
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "Конечно, {name}! На это у меня есть машина. Разобранная, так что вручную."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "Конечно, {name}! Встань на крестик. Его нет. Встань где угодно."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "Сейчас, {name}! Очки на нос. Не для дела, просто нравятся."
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff}, {name}? Просто в теории И на деле. Подозрительно!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "С удовольствием, {name}! Руки, ноги и брови держи подальше."
L["Hold still, {name}, this is perfectly safe. Probably!"] = "Не шевелись, {name}, это совершенно безопасно. Наверное!"
L["Science says you need this, {name}. Who am I to argue?"] = "Наука говорит, тебе это нужно, {name}. А с наукой не спорят!"
L["A small upgrade for you, {name}. No cogs required."] = "Маленькое улучшение, {name}. Без шестеренок!"
L["Take it, {name}, I've a spare. I've three spares of everything."] = "Бери, {name}, это запасное. У меня всего по три запасных."
L["Try this, {name}! Version one had legs. Version two is much better."] = "Попробуй, {name}! У первой версии были ноги. Вторая гораздо лучше."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "Главный механик велит делиться гениальностью, {name}. Вот образец!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "Гномреган навсегда, {name}! Это продлится поменьше, зато бесплатно."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "Рост у меня маленький, {name}, а подарки -- крупные. Держи!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "Не волнуйся, {name}! На курице сработало, и курица в восторге."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "За Гномреган, {name}! Как приятно говорить с кем-то глаза в глаза!"
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "Еще один гном, {name}! Я держу чертеж, ты -- ведро."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "Плоть или шестеренки, {name}, все мы гномы. Некоторых надо смазывать."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "Как гном гному, {name}: а реактор точно выключен?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "Калибровка группы завершена, {name}! Ничего блестящего не трогать."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "Расчеты показывают, {name}: с тобой мы победим. С округлением вверх."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "Если крикну «Воздух!», {name}, не делай вдох. В прошлый раз вышло плохо."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "Строимся, {name}: высокие -- вперед, я -- в безопасности и с умным видом."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "Каждому по одному, {name}! Стандартные детали -- секрет хорошей машины."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "Утро, {name}! На ногах с трех: тостеру нужен был новый двигатель."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "Доброе утро, {name}! Кофе варится сам. Научился. Тревожно."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "Ранний подъем, {name}! Лучшие идеи приходят до завтрака. Взрывы -- тоже."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "Свет вознаграждает доброту, {name}. Я лишь его самый быстрый гонец."
L["Archenon poros, {name}. Your gift is returned."] = "Аркенон порос, {name}. Прими ответный дар."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "Спасибо, {name}. Подвезти бы тебя на Экзодаре, но ты знаешь, как он садится."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "Дар от чистого сердца, {name}. Наару гудят чуть громче. Возвращаю."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "Как любезно, {name}. На Аргусе это высекли бы в кристалле. Держи."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "Из десятка миров, {name}, только язык доброты не пришлось учить."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "Какая доброта, {name}! Почти перевешивает Легион. Почти."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "Спасибо, {name}. По-дренейски это заняло бы одиннадцать минут."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "Конечно, {name}. Наару направляют твои шаги, а это придаст им бодрости."
L["Gladly, {name}. The Light answers those who ask."] = "С радостью, {name}. Свет отвечает тем, кто просит."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "Велен предвидел твою просьбу, {name}. А я -- свое «да»."
L["The Light is not rationed, {name}. Take as much as you like."] = "Свет не по карточкам, {name}. Бери сколько хочешь."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "Конечно, {name}. Кто бегал от Пылающего Легиона, тому это пустяк."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "Сейчас, {name}. Копыта уперты, кристаллы гудят -- держи!"
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "Охотно, {name}. После погони за говорящим кристаллом меж звезд это пустяк."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "Свет с тобой, {name}. Ступай с миром. Или хотя бы во всеоружии."
L["Walk in the Light, {name}. May it shelter you always."] = "Ступай во Свете, {name}. Пусть он всегда хранит тебя."
L["Take this, {name}. My people always travel Light."] = "Держи, {name}. Мы ходим налегке: Свет ничего не весит."
L["Take this, {name}. The Legion is always coming. I'd know."] = "Держи, {name}. Легион всегда на подходе. Уж мне ли не знать."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "Чудеса кончились, {name}. Сойдет и это: {buff}?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "В дорогу, {name}. Моя длится уже двадцать пять тысяч лет."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "Благословлено наару, {name}. Ну, рядом с наару постояли. Считается."
L["Take this, {name}. It glows a bit. Everything we own does."] = "Держи, {name}. Немного светится. У нас все светится."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Аркенон порос, {name}! Дети Аргуса заботятся друг о друге."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "Дом -- там, где двое дренеев, {name}. Сегодня -- здесь."
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "Выше рога, {name}! Двое дренеев, и никто не вспомнил Легион. Прогресс."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "Хвост трубой, {name}! Аргус гордился бы тем, как мы живем в изгнании."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "Держись рядом, {name}. Один мир уже потерян, а эту группу не отпущу."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "Двадцать пять тысяч лет в бегах, {name}. С друзьями идти приятнее."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "Наару назвали бы это братством, {name}. А я -- удачей."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "На моих глазах гибли миры, {name}. Что бы ни ждало впереди -- не страшно."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "Держимся вместе, {name}. Свету проще нас найти, когда мы в одном месте."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "Благодарю, {name}. Гилнеас не забывает добра. Мой нос -- тоже."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Спасибо, {name}. Прими мою благодарность и мой лучший вой."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "Спасибо, {name}. Будь у воргенов хвосты, мой бы сейчас вилял."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "Теперь у тебя друг на всю жизнь, {name}. Верность -- наш конек."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "Зверь во мне хочет рычать, {name}. Гилнеасец во мне велит сказать спасибо."
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "Очень ценю, {name}. Пожать бы руку, да когти. Вот, держи лучше."
L["We walled ourselves off for years, {name}. You make that look silly."] = "Годами мы прятались за стеной, {name}. Глядя на тебя, не пойму зачем."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "Спасибо, {name}. За тобой место у огня. Лучшее место."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Разумеется, {name}. Стой смирно, я не кусаюсь. Почти."
L["Right you are, {name}. Stand steady now."] = "Как скажешь, {name}. Теперь стой ровно."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "Сейчас, {name}. Стоять! Всегда хотелось кому-нибудь это сказать."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "Охотно, {name}. В дождь и в солнце. В Гилнеасе -- в дождь."
L["Certainly, {name}. I'll try not to shed on you."] = "Конечно, {name}. Постараюсь на тебя не линять."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "Ни слова больше, {name}. Эти уши слышат просьбу раньше, чем ее задумают."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "Конечно, {name}. Куда вежливее того, кто в прошлый раз кинул мне палку."
L["Stay off the moors after dark, {name}. Take this."] = "Не ходи по пустошам после заката, {name}. Держи."
L["Keep your wits about you, {name}. Something is always hunting."] = "Держи ухо востро, {name}. Кто-то всегда на охоте."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "Могло быть и раньше, {name}, но по пути подвернулось, за кем погнаться."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "Держи, {name}. Нет, вкусняшку не надо. Ну... разве что маленькую."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "Гилнеасцы всегда помогают, {name}. Когти -- просто часть наряда."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "Гилнеасское средство, {name}: от простуды, хандры и проклятий. Кроме моего."
L["Run with this, {name}. Trust me, I know about running."] = "Беги с этим, {name}. Поверь, в беге я знаю толк."
L["Fetched this for you, {name}. Don't make a thing of it."] = "Апорт, {name}. Только не делай из этого событие."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "Нас связывает проклятие, {name}, но Гилнеас связывает крепче."
L["No need to explain the ears to you, {name}."] = "Тебе про уши объяснять не надо, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "Шерсть, туман и дождь, {name}. Только гилнеасец поймет все три."
L["Pack looks after pack, {name}. Always has."] = "Стая бережет стаю, {name}. Так было всегда."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "Закон стаи, {name}: никто не отбивается, и никто не вспоминает про блох."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "Снова стая, {name}. Кто бы знал, как ее не хватало."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "Беду я учую раньше всех, {name}. Единственная польза от проклятия."
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "Если я завою, {name}, это боевой клич. Наверное. Не смотри так."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "Веди, {name}. Я -- рысцой. Несолидно, зато куда быстрее."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "Снова ночь, {name}. Время моего лучшего и худшего. Это -- лучшее."
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "Глянь, какая луна, {name}. Не обращай внимания, я не вою. Почти."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "Ночной Гилнеас -- это туман и шаги, {name}. Теперь шаги -- это я."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "Утро, {name}. Встать бы пораньше, да коврик у камина уж больно теплый."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "Утром пахнет дождем, {name}. В Гилнеасе все пахло дождем."
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "Уже на ногах, {name}? На моем счету два кролика. Чисто для зарядки."
L["Throm-ka, {name}! Honour is repaid."] = "Тром-ка, {name}! Долг чести уплачен."
L["You give freely, {name}. I return the favour."] = "Ты даешь от души, {name}. Я отвечаю тем же."
L["Orcs keep their thanks short, {name}. Thanks."] = "Орки благодарят коротко, {name}. Спасибо."
L["Orcs return every blow twice, {name}. The kind ones too."] = "Орки отвечают на удар вдвойне, {name}. На добрый -- тоже."
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "Ты мне, я тебе. Орочья поэзия, {name}. Рифма случайная."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "В старые времена за такое платили кабаном, {name}. А это дольше хранится."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "Долг чешется хуже песка Дуротара, {name}. Вот. Больше не чешется."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "Сильная штука, {name}. Теперь и кодо поборю. И ты поборешь."
L["Dabu, {name}. It is done."] = "Дабу, {name}. Сделано."
L["Hold still, {name}. Strength for the fight ahead."] = "Не двигайся, {name}. Это сила для грядущей битвы."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "Попроси орка о помощи -- получишь, {name}. Попроси о тонкости -- жди."
L["Help, yes. Hugging, no. Hold still, {name}."] = "Помощь -- да. Объятия -- нет. Замри, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "Нужно: {buff}? Есть: {buff}, {name}. Следующий."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "Не дергайся, {name}. Помогаю я с тем же лицом, что и дерусь."
L["Short question, short answer, {name}: yes."] = "Короткий вопрос, короткий ответ, {name}: да."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Лок'тар огар, {name}! Возьми это в бой. Трактирная драка тоже считается."
L["Blood and thunder, {name}! Go and earn your glory."] = "Кровь и гром, {name}! Иди и добудь себе славу."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "У орков, {name}, сделать тебя сильнее -- это признание в симпатии."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "Орк дарит просто так? Никому ни слова, {name}. Это портит образ."
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "Мне велели быть дипломатичнее, {name}. Вот она, моя дипломатия."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "Пойди ударь кого-нибудь за меня, {name}. Или подожги. Орки неприхотливы."
L["Don't thank me, {name}. Just win, and do it loudly."] = "Не благодари, {name}. Просто победи, и погромче."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "Речь бы толкнуть, {name}, да там в основном крик. Просто бери."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Тром-ка, {name}! В тебе сильна кровь кланов."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "Орк, {name}! Наконец-то кто-то орет на моей громкости."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "Хоть Северный Волк, хоть Черная Гора, {name}, ругаемся мы как родня."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "Между орками слова не нужны, {name}. И хорошо. У меня они кончились."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "План, {name}: бьем. Вопросы? Нет? Хороший план."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "Настоящий отряд, {name}: шумный, злой и для разнообразия весь заодно."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "Держись отряда, {name}. Сила в числе. И в топорах."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "Упадешь -- вынесу, {name}. Ворча всю дорогу, но вынесу."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "Бейся достойно, {name}, -- вечером разделим костер. И похвальбу."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Спасибо, {name}. Это согрело бы мне сердце, если бы оно еще билось."
L["Such warmth, for one so cold? Returned in full, {name}."] = "Столько тепла для остывшего сердца? Возвращаю сполна, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "Спасибо, {name}. Покраснеть бы, да кровь до лица уже не доходит."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "Благодарность по гроб жизни, {name}. В моем случае -- буквально."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "Как любезно, {name}. Меня перевели из «усопших» в «слегка усопшие»."
L["You've added years to my life, {name}. Shame it already ended."] = "Это продлит мне жизнь на годы, {name}. Жаль, она уже кончилась."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "Это чувствуется, {name}, а я нынче мало что чувствую. На, почувствуй."
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "Пожать бы тебе руку, {name}, да моя держится на честном слове."
L["Certainly, {name}. Try not to die. It's overrated."] = "Конечно, {name}. Не умирай. Смерть переоценивают."
L["You need only ask, {name}. The dead are patient."] = "Достаточно просто попросить, {name}. Мертвые терпеливы."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "Обращайся к мертвым, {name}: у нас редко бывают другие планы."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "Конечно, {name}. Отойди, а то вдруг что-нибудь на тебя отвалится."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "Минутку, {name}. От трупного окоченения рука плохо гнется."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "Приятно, когда просят о чем-то, {name}, кроме дороги на кладбище."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "С радостью, {name}. Отвлекает от запаха. Моего, в смысле."
L["Stay among the living a little longer, {name}."] = "Побудь среди живых еще немного, {name}."
L["Take this, {name}. The grave can wait."] = "Держи, {name}. Могила подождет."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "В Лордероне у меня была лечебница, {name}. Привычки живучее меня."
L["No charge, {name}. The apothecaries would have made you sign something."] = "Бесплатно, {name}. Аптекари заставили бы тебя что-нибудь подписать."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "Подарок из могилы, {name}. Не бойся, он мытый."
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "Каждому телу нужна поддержка, {name}. Моему -- в основном нитки."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "Знаю, куда попадают герои, {name}. Я там живу. Держи."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "Держи, {name}. С собой в могилу ничего не унесешь -- проверено."
L["We Forsaken must look after each other, {name}."] = "Мы, Отрекшиеся, должны держаться друг друга, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "Между нами, трупами, {name}: сохранность у тебя отличная."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "Потеряешь палец -- дам запасной, {name}. Отрекшиеся делятся."
L["Is your jaw clicking too, {name}, or is that just me?"] = "У тебя тоже челюсть щелкает, {name}, или только у меня?"
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "Не умирай, {name}. Альтернатива проверена лично -- не рекомендую."
L["If I fall down, {name}, give it a minute. Old habit."] = "Если я упаду, {name}, подожди минутку. Старая привычка."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "Передовая за мной, {name}. Что самое страшное может случиться? Снова?"
L["Keep upwind of me, {name}. It's better for morale."] = "Держись с наветренной стороны, {name}. Ради боевого духа."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "Прошлая группа, {name}, кончилась для меня склепом. Давай лучше."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "У мертвых ужасный режим, {name}. Приятно хоть раз побыть в компании."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "Полночь, {name}: лучший час, чтобы разгуливать, когда положено лежать."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "Живые спят, {name}. Мы, Отрекшиеся, зовем это тихой сменой."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "Уже утро, {name}? А у меня бессонная ночь. И бессонное десятилетие."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "Солнце встало, {name}. Я постою в тени, если ты не против. А то шелушится."
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "Ранний подъем, {name}. Мертвые не залеживаются. Да и не спят вовсе."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "Мать-Земля видела твою доброту, {name}. И пихнула меня. Весьма ощутимо."
L["Thank you, {name}. May the winds guide you."] = "Спасибо, {name}. Да ведут тебя ветра."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "Спасибо, {name}. Это трогает. А таурена тронуть с места ох как непросто."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "До сердца таурена высоко, {name}. А тебе удалось."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "Пробрало от рогов до копыт, {name}. Возвращаю от копыт до рогов."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "Что посеешь, {name}, то и пожнешь. Вот урожай."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "Это достойно пира, {name}. Пир подождет, а {buff} -- нет."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "Спасибо, {name}. Понадобится стена, за которой спрятаться, -- обращайся."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "Конечно, {name}. Выше голову, и мир тебе. Насчет «выше» -- это ко мне."
L["Ask and it is given, {name}. The herd shares what it has."] = "Проси, и дано будет, {name}. Племя делится тем, что имеет."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "Конечно, {name}. Отойди на шаг: я это делаю всем телом."
L["Gladly, {name}. Mind the tail."] = "С радостью, {name}. Осторожно, хвост."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "Мать-Земля щедра, {name}. И ее самые крупные дети -- тоже."
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "С радостью, {name}. Таурены медленно злятся и быстро помогают. Ну, почти."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "Отказать тебе, {name}? Да предки меня потом всю вечность пилить будут."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "Ступай с Матерью-Землей, {name}. Она повсюду, так что не заблудишься."
L["May An'she light your path, {name}."] = "Да озарит Ан'ше твой путь, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "Похоже, тебе не помешает друг, {name}. А я очень большой друг."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "Держи, {name}. Мать-Земля не простит, если пройти мимо."
L["Tread lightly, {name}. Take it from someone who never has."] = "Ступай легко, {name}. Совет от того, кто так не умеет."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "Ветер сказал, что ты тут пройдешь, {name}. Ветер -- жуткий сплетник."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "Держи, {name}. Одолжить бы и кодо, да он не такой щедрый, как я."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "Шу'хало говорят: неси, что можешь, ради других, {name}. А я могу много."
L["The Earth Mother watches over us both, {name}."] = "Мать-Земля хранит нас с тобой, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "Предупредите дверные проемы, {name}: нас теперь двое."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "Равнины или горы, {name}, а сердце у шу'хало большое."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "Рога и шлемы, {name}. Эту боль поймет только таурен."
L["Get behind me, {name}. There's room back there for the whole party."] = "Встань за меня, {name}. Там поместится вся группа."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "Племя держится вместе, {name}. Берегись моих копыт -- племя уже научилось."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "Впереди низкие потолки, {name}? Узнаю об этом раньше всех. Держи."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "Меня трудно разозлить, {name}, но обиды я помню за всю группу."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "Нужна стена, {name}, чтобы спрятаться? Я -- почти стена. Сюда."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "Ан'ше встает, {name}, и мы вместе с ним. Я -- помедленнее."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "Солнце -- око Ан'ше, {name}. Он смотрит, так что изобразим занятость."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "Утро, {name}. Кодо проснулись, трава в росе, а это -- тебе."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "Му'ша несет ночной дозор, {name}. Попрошу ее приглядеть за тобой."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "Луна взошла, {name}. Му'ша тебя видит и одобряет. Мы это обсудили."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "Поздно, {name}. Кодо спят и храпят, как гром. Держи."
L["Ya be too kind, {name}! Dis one be from me."] = "Ай, доброта-то какая, {name}! А это тебе от меня."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "Спасибо, мон! Духи тебе улыбаются, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "Хорошее моджо от тебя, {name}. Лови ответное, поострее."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "Бвонсамди будет очень разочарован, {name}. Спасибо, мон."
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "Отличная работа, {name}. Почти как моя. Почти."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "Тролль может отрастить руку, {name}. А честь не отрастишь. Держи."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "Из-за тебя тролль улыбается, {name}, а зубов у нас много."
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "Лоа ведут счет, {name}, и теперь ты у них на хорошем счету."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "Ясное дело, {name}. Не дергайся, моджо не любит движущихся целей."
L["No worries, {name}. Da loa got ya covered."] = "Не боись, {name}. Лоа тебя прикроют."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "Держись подальше от вуду, {name}. ...Кроме этого вуду. Это хорошее."
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "Закрой глаза, {name}. Моджо стесняется, когда смотрят."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "Дважды просить не надо, {name}. Да и один раз -- с натяжкой."
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "Легко, {name}. Тролль -- это в основном понты. Остальное -- вот."
L["Ya asked real polite, {name}. Polite get da good stuff."] = "Вежливо просишь, {name}. А вежливым -- самое лучшее, мон."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "Лоа за тобой следят, {name}. Они страсть какие любопытные."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Гляди в оба, {name}. Возьми вот это с собой."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "Сразу видно ценителя качества, {name}. Держи: качество."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "Держи, {name}. Ходи, будто джунгли твои. Я так и хожу."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "Моджо нужно всем, {name}. У меня его столько, что раздаю."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "Кое-что для тебя, {name}. Не спрашивай, где лоа это взяли."
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "Давай, {name}. Кто теперь тебя съест, тот получит несварение."
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "Теперь ты выглядишь опасно, {name}. Почти как тролль."
L["Hey, {name}! Always good to see family, mon."] = "Эй, {name}! Родню видеть всегда в радость, мон."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "Весь Азерот ходит прямо, {name}. А у нас -- стиль."
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "Эй, {name}, клыки у тебя что надо. Мои тоже, само собой."
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "Все тролли -- родня, {name}. Даже те, кто мне еще золото должен."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "Держись рядом, {name}. Тролли регенерируют, а вам надо поосторожнее."
L["Dis crew got style, {name}. Now it got mojo too."] = "У банды есть стиль, {name}. Теперь и моджо есть."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "Заходим вместе, {name}, выходим вместе. Вот и весь план, мон."
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "Сегодня никто не падет, {name}. Бвонсамди подождет следующую группу."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "Не высовывайся, {name}. А я высунусь: кто-то же должен блистать."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "Ночь -- лучшее время для моджо, {name}. Никто не видит, откуда оно."
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "Джунгли просыпаются ночью, {name}. И я тоже. Держи, свеженькое."
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "Луна высоко, {name}, духи неспокойны. Это их от тебя отгонит."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "Такая учтивость делает тебе честь, {name}. Почти такую же, как мне."
L["How gracious, {name}. Allow me to return the favour."] = "Как великодушно, {name}. Позволь отплатить тем же."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "Спасибо, {name}. Такого сияния со мной не было с... ну, с утра."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "Мило, {name}. Син'дорай от бесплатной магии не отказываются. Спроси любого."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "Изысканно, {name}. Уж я-то знаю: принимаю только изысканное."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "Прелестно, {name}. Весь день буду этим хвастать. Больше обычного."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "Спасибо, {name}. Даже к моей золотой отделке идет. У тебя есть вкус."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "Возвращаю тем же, {name}. Ну, чуть красивее. Ничего не могу поделать."
L["Naturally, {name}. Only the finest for you."] = "Разумеется, {name}. Для тебя только лучшее."
L["For you, {name}? Of course. The sun gives freely."] = "Для тебя, {name}? Конечно. Солнце щедро на дары."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "Терпение, {name}. Сияние не торопят, им любуются."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "Конечно, {name}. {buff} -- с безупречной осанкой."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "Какая вежливая просьба, {name}. В Луносвете это главное."
L["One moment, {name}. I never cast anything without checking my hair."] = "Минутку, {name}. Не колдую, не проверив прическу."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "Сию минуту, {name}. Заставлять ждать -- ужасно немодно."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Анар'ала белорэ, {name}. Да ведет тебя солнце -- и в лучшем ракурсе."
L["Shorel'aran, {name}. Fight with elegance."] = "Шорел'аран, {name}. Сражайся изящно."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "Держи, {name}. Что бы там ни было -- это лишь временная неудача."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "Каждый заслуживает сиять, {name}. Чуть меньше, чем я, конечно."
L["The sun is with you, {name}. I simply held the door for it."] = "Солнце с тобой, {name}. Я лишь придерживаю ему дверь."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "Бери, {name}. Солнечный Колодец снова с нами, можно и расщедриться."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "Для тебя, {name}: {buff}, с легким ароматом Луносвета."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "Держи, {name}. Ручная работа Луносвета, так что не поцарапай."
L["The Sunwell shines for us both, {name}."] = "Солнечный Колодец сияет для нас с тобой, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "Двое син'дорай в одном месте, {name}. День стал вдвое изящнее."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "И ты тоже, {name}? Двое син'дорай, одно зеркало. Придется по очереди."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "Как феникс, {name}: мы вечно возрождаемся. И всегда красиво."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "Не отставай, {name}. У нас репутация: появляться красиво."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "Встань где свет получше, {name}. Раз уж драться, то красиво."
L["A party at last, {name}. I did dress for one."] = "Наконец-то компания, {name}. Я как раз при параде."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "Солнце светит всем нам, {name}. В основном мне, но делится."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "Это тебе, {name}, а это -- имиджу группы. Им занимаюсь я."
L["The sun has risen, {name}, and so have I. We coordinate."] = "Солнце встало, {name}, и я тоже. Мы действуем согласованно."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "Над Кель'Таласом рассвет прекраснее, {name}, но и этот сойдет. Едва."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "Утренний свет, {name}. Самый выгодный час. Для нас с тобой, разумеется."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "Твоя щедрость отмечена, {name}. В трех экземплярах. Сурамар помнит друзей."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Весьма любезно, {name}. Позволь ответить равным даром."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "Спасибо, {name}. Десять тысяч лет под куполом -- я все еще это репетирую."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "Дар без встречного долга? Двор упал бы в обморок. Спасибо, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "Возвращаю, {name}. Мы тщательно ведем учет добра. И обид."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "Упомяну тебя при первом арканисте Талисре, {name}. Даже с похвалой."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "Весьма любезно, {name}. В Сурамаре был бы банкет. Считай, что он был."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "Послать бы тебе благодарственное письмо, {name}, но так быстрее."
L["Of course, {name}. A little arcane polish, just for you."] = "Конечно, {name}. Немного тайного лоска, специально для тебя."
L["A reasonable request, {name}. Granted."] = "Разумная просьба, {name}. Быть по сему."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "Разумеется, {name}. Краткая версия: полная занимает лунный цикл."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "Просьба -- как свежо. При дворе только требовали. Держи, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "Готово, {name}, и бесплатно. Элисанда потребовала бы за это услугу."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "Вот, {name}. Кланяться не нужно. Хотя легкий кивок был бы мил."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "Конечно, {name}. Оттачиваю это со времен, когда у городов не было стен."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Возьми, {name}. Дары тайной магии не для праздных."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Искра магии Сурамара для тебя, {name}. Распорядись ею мудро."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "Однажды пришлось жить без магии, {name}. Не советую. Держи."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "Мир за куполом такой большой, {name}. И так скудно зачарован. Держи."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "Чародейское вино -- классика, {name}, а в дорогу -- {buff}."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "Прошу, возьми, {name}. Отказ от гостеприимства Сурамара -- это грубо. Очень."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "Держи, {name}. Говорят, так чужеземцы здороваются. Очаровательный обычай."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "Держи, {name}. Магия в запасе портится -- Сурамар это усвоил."
L["Suramar's children shine together again, {name}."] = "Дети Сурамара снова сияют вместе, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "Шал'дорай, {name}! Чародейское вино с собой? Здешнее -- просто... виноград."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "Дитя Сурамара, {name}! Постарайся не слишком восхищаться остальным миром."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "Мы пережили Легион и иссыхание, {name}. Остальное -- светская болтовня."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "Экспедиция, {name}! В Сурамаре на это нужны шесть разрешений и маскарад."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "Купол нас берег, {name}. Теперь придется беречь друг друга. С радостью."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "Магия всем, {name}. Двор счел бы это расточительством, а я -- компанией."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "Следуй за мной, {name}. У меня десять тысяч лет опыта ходьбы в ногу."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "В группе принято делиться магией, {name}. Как ново. Мне даже нравится."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "Наконец-то ночь, {name}. Добавить пару тысяч фонарей -- и почти Сурамар."
L["Under the dome it was always night, {name}. I feel quite at home."] = "Под куполом всегда была ночь, {name}. Чувствую себя как дома."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "Звезды высыпали, {name}. В Сурамаре были лучше. Сойдут и эти."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "Дневной свет, {name}. Десять тысяч лет под куполом, а он все еще пугает."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "Ранний час, {name}. Двор не вставал до полудня. Я исправляюсь."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "Утро, {name}. Солнце здесь такое... незачарованное. Держи вот это."
L["A favour for a favour, {name}! Pleasure doing business."] = "Услуга за услугу, {name}! Приятно иметь с тобой дело."
L["Thanks, {name}! Consider your account settled in full."] = "Спасибо, {name}! Считай, счет закрыт полностью."
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "Ох, {name}. Выставить бы счет, но накатила сентиментальность. Пройдет."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "Спасибо, {name}! Мелкий шрифт проверен. Его нет. Странно!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "Возвращаю с процентами, {name}. Без процентов. Не привыкай."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "Спасибо, {name}! Твой новый статус: «особо ценный клиент»."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "Назвать бы ракету в твою честь, {name}, да ракеты у меня не живут. Спасибо!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "Вообще-то это стоит пятьдесят золотых, {name}. Но будем в расчете."
L["You got it, {name}! Time is money, friend!"] = "Сделаю, {name}! Время -- деньги, друг!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "Договорились, {name}! Запишу на твой счет. Шучу!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "Сейчас, {name}! Держи: {buff}. Не понравится -- примем назад."
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff}, {name}! Чаевые по желанию. Желательно. По желанию."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "Быстро, дешево или качественно, {name}? Сегодня -- все три. Только никому."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "Без проблем, {name}! В этот раз без взрывов, обещаю. Почти обещаю."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "Для тебя, {name}? Бесплатно. Запишешь это -- буду все отрицать."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "За счет заведения, {name}. Только торговому принцу ни слова."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "Высший сорт, без комиссии, {name}. Только сегодня!"
L["Free sample, {name}! If you like it, you know where to find me."] = "Бесплатный образец, {name}! Понравится -- знаешь, где меня найти."
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "Держи, {name}. Если сегодня рядом что-то взорвется, это совпадение."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "Репутация -- актив, {name}. Держи: {buff}. Запишу в баланс."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "Держи, {name}. Безопасность превыше всего! Ну, или где-то в списке."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "Рекордная скорость, {name}! Рекорд мой. Только что установлен."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "Кая'Кола дает идеи, {name}, а это -- все остальное. Бери!"
L["Anything for a fellow entrepreneur, {name}!"] = "Для коллеги по бизнесу ничего не жалко, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "Лучшие с Кезана снова вместе, {name}. Держи руку на кошельке."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "Гоблин, {name}? Тогда понимаешь: такая скидка -- огромная редкость."
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "Гоблины берегут гоблинов, {name}. Это дешевле охраны."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "Групповой тариф, {name}! Всем за полцены. От бесплатного."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "По моему контракту не умирают, {name}. Потом бумаг не оберешься."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "Добычу делим поровну, {name}. Считаю я. Доверься мне."
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "Тимбилдинг, {name}! Ты всех усиливаешь, и все тебе должны."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "Держимся вместе, {name}. Наемники стоят золота, друзья -- только этого."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "Кто рано встает, тому золото, {name}! Держи даром. Другим пташкам ни слова."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "Утро, {name}! Рынки откроются через час. А пока -- приступ щедрости."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "Рано на ногах, {name}? Умно. Время -- деньги, а утром оно дешевле всего."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "Спасибо, {name}! Караван всегда платит за добро. Обычно веревочками."
L["How kind, {name}! You're on the caravan's good list now."] = "Как мило, {name}! Теперь ты у каравана на хорошем счету."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "О, это я оставлю себе, {name}! Я все оставляю. А это тебе."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "Спасибо, {name}! Держи обратно. Ну, новое. Почти не ношенное."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "У меня уши встали торчком, {name}. Это от большого удовольствия."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "У костра, {name}, в этой байке появится песчаный червь. Спасибо!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "Завернуть бы подарок, {name}, но вся моя обертка -- чужие старые карты."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "Альпаки все видели, {name}. Всем расскажут, какая у тебя доброта. Спасибо!"
L["Of course, {name}! Shake the sand out and hold still."] = "Конечно, {name}! Вытряхни песок и не шевелись."
L["Coming right up, {name}! Caravan service, no waiting."] = "Сейчас будет, {name}! Караванный сервис, без очередей."
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "Конечно, {name}! Сейчас откопаю... веревка, камни, красивый камень... вот!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "Погоди, {name}! Хвост мешает, секунду... вот!"
L["One {buff}, {name}! Only slightly sandy."] = "Держи, {name}: {buff}! Почти без песка."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "Проси вульперу, {name}, -- что-то получишь. Обычно странное. Не сегодня!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "Держи, {name}! Вульперы обожают дарить. Почти так же, как находить."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "Каждому путнику нужно что-то в дорогу, {name}. Проверено: не камень."
L["Keep this, {name}. The desert is long and the water is short."] = "Держи, {name}. Пустыня велика, а воды мало."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "Валялось тут, {name}. Шучу! Свеженькое. Бери!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "Держи, {name}. Лучшее из моего мешка, а мешок у меня большой."
L["In the dunes you share your shade and your spells, {name}. Here."] = "В дюнах делятся тенью и заклинаниями, {name}. Держи."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "Держи, {name}: {buff}. Поторговаться бы, да тебе некогда."
L["A gift from the whole caravan, {name}! They'll never know."] = "Подарок от всего каравана, {name}! Они и не узнают."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "В дорогу, {name}. Дорога -- это лучшее. Дорога и перекусы."
L["A fellow wanderer! The caravan is never far, {name}."] = "Еще одна бродячая душа! Караван всегда рядом, {name}."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "Ушки на макушке, {name}! Приятно поделиться чарами с другой лисой."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "Как вульпера вульпере, {name}: у меня три запасные ложки, если что."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "Вол'дун вырастил нас с тобой, {name}. Песок в шерсти, удача в мешке."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "Правила каравана, {name}: вместе, вода поровну, альпаку не продавать."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "Все блестящее внутри, {name}, -- чур, мое. Закон каравана."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "Всем по одному, {name}! Караван идет со скоростью самой медленной альпаки."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "Держи мешок закрытым, {name}. Я не нарочно. Вещи сами за мной ходят."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "В городе заблужусь, {name}, в пещере -- никогда. Пещера -- дом без аренды."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "Вульперы ходят ночью, {name}: песок прохладный, скорпиды сонные."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "Ночи в пустыне холодные, {name}. Вот, что-то теплое. Почти."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "Звезды вышли, {name}. Каждая -- указатель, если умеешь читать. Я не умею."
L["A kindness returned is a kindness doubled, {name}."] = "Добро, возвращенное добром, удваивается, {name}."
L["Thank you, {name}. You have restored my balance."] = "Спасибо, {name}. Мое равновесие восстановлено."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "Где-то сейчас оголодал один ша. Спасибо, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "Спасибо, {name}. Аиса бы поклонилась, Цзи бы ликовал. Я -- все сразу и криво."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "Спасибо, {name}. Вспомню тебя за следующей трапезой. И за той, что после."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "Чэнь говорил: не отказывайся от подарков. И от выпивки. Спасибо, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "Уже почти задремалось, {name}, но так лучше. Чуть-чуть. Спасибо."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "Хозен бы чем-нибудь кинул, {name}. А меня воспитывали лучше. Спасибо."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "Конечно, {name}. Терпение -- и готово. Терпение -- это медленная часть."
L["With pleasure, {name}. A kind deed is never wasted."] = "С удовольствием, {name}. Доброе дело не пропадет даром."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "Сейчас же, {name}. Быстро -- по меркам пандарена, а это немного."
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "Мастер Шан Си учил: помогай просящим, {name}. А еще: пригнись."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "Мастер тушуй сперва заставил бы тебя медитировать, {name}. Это пропустим."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "Для тебя что угодно, {name}. Кроме последнего пельменя. Не будем глупить."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "Заварено покрепче, {name}: {buff}. Рецепт -- секрет."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Держи, {name}. А потом, может, по чашечке чая?"
L["Balance in all things, {name}. Now go with a light heart."] = "Во всем нужно равновесие, {name}. Ступай с легким сердцем."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "Держи, {name}. Груммл продал бы тебе это за оберег на удачу."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "Цзинь-юй говорят, воды это предсказали, {name}. Они часто так говорят."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "Хоцзинь: сперва действуй. Тушуй: сперва думай. А я: держи, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "Ради этого пандарен встал с места, {name}. Цени."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "Бейся как монах, {name}: спокойно, быстро, а потом долгий обед."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "Ступай спокойно, {name}. Черепаха дошла куда надо и ни разу не поспешила."
L["We must share a brew when the road allows, {name}!"] = "Как дорога позволит, разделим кружку хмельного, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "Шэнь-Цзинь Су нами гордится, {name}. Или спит. Не разберешь."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "Двое пандаренов вместе, {name}. Где-то сейчас вздрогнул один трактирщик."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "Лю Лан бы одобрил, {name}: мы с тобой оба далеко от дома."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "Сначала бой, потом еда, {name}. Именно в таком порядке. Никогда наоборот."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "Держимся вместе, {name}, как пельмени в пароварке: тепло и дружно."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "Идем как один, {name}. Медленно, может, но как один."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "Равновесие, {name}: один бьется, другой лечит, третий несет закуски. Это я."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "Если падем, {name}, то вместе, а потом вздремнем. Лучше не надо."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "На ногах раньше чая, {name}? Смело. Держи, вместо чая."
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "Утро, {name}. Сначала это, потом завтрак, потом второй завтрак."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "Новый день, {name}, и еще никто ничего не пролил. Начнем потихоньку."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "Первый сон позади, {name}, второй впереди. Быстрее, пока не сплю."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "Поздно, {name}. Хмелевары спят. А варево, подозреваю, бродит."
L["Midnight snack time, {name}. This is the appetiser."] = "Время полночного перекуса, {name}. Это закуска."
L["Your kindness is noted, {name}. Dragons do not forget."] = "Твоя доброта замечена, {name}. Драконы не забывают."
L["Thank you, {name}. Returned on swift wings."] = "Спасибо, {name}. Ответ летит на быстрых крыльях."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "Крылья, огонь, чешуя, {name} -- и все же мне нужна помощь? Трогательно."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "Поклониться бы, {name}, да в прошлый раз крылья снесли стол. Спасибо."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "Это -- в мою сокровищницу, {name}. Добрые дела -- мое единственное золото."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "Меня создавали оружием, {name}. Эта часть мне нравится больше. Спасибо."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "Спасибо, {name}. Гневион закатил бы по этому поводу речь. А я не стану."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "Возвращаю с огоньком, {name}. Совсем небольшим. Я тренируюсь."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Хорошо, {name}. Не шевелись, не хотелось бы тебя подпалить."
L["Granted, {name}. A dragon keeps its word."] = "Исполнено, {name}. Дракон держит слово."
L["Certainly, {name}. Stand clear of the tail."] = "Разумеется, {name}. Отойди от хвоста."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "Конечно, {name}. Так еще делают? Десять тысяч лет сна -- не шутка."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "С радостью, {name}. Во мне все пять драконьих стай, и все пять согласны."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "Сию минуту, {name}. Драконья помощь в удобном компактном облике."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "Конечно, {name}. Нелтарион только приказывал. Просьба куда приятнее."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "Держи, {name}. Даже дракону нужны союзники. Особенно дракону моего роста."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Дар с Драконьих островов, {name}. Легкого полета."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "Алекстраза говорит, что каждая жизнь драгоценна, {name}. Начну с твоей."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "Десять тысяч лет сна без единого доброго дела, {name}. Наверстываю."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "Скажи всем, что это сделал дракон, {name}. Звучит куда солиднее, чем было."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "Приказ командира чешуи, {name}. Я не командир, но чешуя-то есть."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "Держи, {name}. Древняя драконья магия, лишь слегка просроченная."
L["A dragon giving, {name}, not taking. I am trying something new."] = "Дракон дарит, а не отбирает, {name}. Пробую что-то новое."
L["The Forbidden Reach feels far behind us now, {name}."] = "Запретный край теперь далеко позади, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "Два драктира в одном месте, {name}. Осторожнее с крыльями: четырем тут тесно."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "Помнишь, как все в мире было для нас в новинку, {name}? Да и сейчас почти все."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "В облике смертного нас не отличить, {name}. Но между нами: в чешуе мы краше."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "Скажи, когда дышать огнем, {name}. И, пожалуйста, когда не надо."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "После пробуждения вокруг были одни чужаки, {name}. Эта компания куда лучше."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "Нелтарион создал нас бойцами-одиночками, {name}. Мы доработали проект."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "Держись подальше от моего хвоста, {name}. Он еще не решил, на чьей он стороне."
L["A flight of our own, {name}. So this is what the dragons meant."] = "Своя собственная стая, {name}. Так вот о чем говорили драконы."
L["It is good to see one of our own, {name}."] = "Как хорошо видеть своих, {name}."
L["Our people are few, {name}. That makes each of us count."] = "Нас немного, {name}. Потому каждый на счету."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "Спасибо, {name}. Альянс своих не бросает, а сегодня свой -- это я."
L["Kindness answered, {name}. For the Alliance!"] = "Добром на добро, {name}. За Альянс!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "В Штормграде есть статуя для каждого героя, {name}. Замолвлю словечко за твою."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "По-альянсовски, {name}: ты мне, я тебе, а за выпивку платит дворф."
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "Генн бы зарычал, Мурадин бы обнял, {name}. А я просто отвечу тем же."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "Будь у Альянса медали за манеры, {name}, на твоей накидке не хватило бы места."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "Возвращаю сполна, {name}. Союзник, что дает первым, стоит целого гарнизона."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "Конечно, {name}. Альянс -- это союз. Само название обязывает."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Сейчас же, {name}. Альянс не оставит друга в нужде."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "Конечно, {name}. Так записано в уставе Альянса. Где-то ближе к концу."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "Приказ Альянса, {name}: {buff}. Вступает в силу немедленно."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "Для союзника что угодно, {name}. В пределах разумного. Это -- вполне в пределах."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "Сию минуту, {name}. В ШРУ знали, что ты попросишь. Мне сообщили только что."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "За Альянс, {name}! Не теряй сил -- теперь их даже больше."
L["Onward, {name}. The Alliance is with you."] = "Вперед, {name}. Альянс с тобой."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "Держи, {name}. Сделай это гном, тут было бы двенадцать рычагов."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "Подарок от Альянса, {name}. Мы раздаем такие со Второй войны."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "Выше нос, {name}. Где-то в Штормграде бард уже пишет об этом балладу."
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "Каждый союзник на счету, {name}. Считаю лично: ты пока в любимчиках."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "Андуин велел бы делиться, {name}, а огорчать его не хочется."
L["Together we stand, {name}. For the Alliance!"] = "Вместе мы выстоим, {name}. За Альянс!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "Итак, {name}: щиты выше, головы ниже, и в атаку не раньше плана."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "Лучший отряд, какой только выставлял Альянс, {name}. Ну, или ближайший."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "Вместе мы почти полк, {name}. Маленький, но хорошо одетый полк."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "Прикрывайте друг другу спины, {name}. Альянс строили те, кто так и делал."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "Сила и честь, {name}. И, как выясняется, доброта. Возвращаю сполна."
L["The Horde takes care of its own, {name}."] = "Орда заботится о своих, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "Сила за силу, {name}. Вот и вся дипломатия Орды."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "Твое имя стоило бы высечь на вратах Оргриммара, {name}, но там нет места. Спасибо."
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "Галливикс выставил бы тебе счет, {name}. А от меня -- вот это."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "Тебя никто не обязывал, {name}. Потому Орда это и запомнит."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "В Орде не говорят «спасибо» дважды, {name}. Так что один раз, но от души."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "Будет сделано, {name}. За Орду и за всех, кто вежливо просит."
L["You only had to ask, {name}. The Horde answers."] = "Стоило лишь попросить, {name}. Орда откликается."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "Обычно Орда помогает топорами, {name}. Сегодня -- {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "Готово, {name}. Без речей. Их в Орде и так хватает."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "Просьба принята, {name}. По меркам Оргриммара -- это договор."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "Просить -- не слабость, {name}. Слабость -- отказать союзнику."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "За Орду, {name}! Да пребудет с тобой сила -- вот, держи немного."
L["Go with honour, {name}. Victory awaits."] = "Ступай с честью, {name}. Победа ждет."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "Соверши что-нибудь достойное песни, {name}. Громкой. Орда любит погромче."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "Держи голову выше, {name}. В Орде всегда находилось место для отверженных."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "Держи, {name}, и вот тебе мудрость Орды: бей первым, не извиняйся никогда."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "Победа или смерть, {name}. Я за победу, так что держи."
L["Like a mak'gora, {name}, except everybody wins. Here."] = "Как мак'гора, {name}, только побеждают все. Держи."
L["Our strength is each other, {name}. For the Horde!"] = "Мы сильны вместе, {name}. За Орду!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "Вперед, {name}. Орда наступает вместе. Отступает... официально никогда."
L["Together we're a war band, {name}. Apart, we're just loud."] = "Вместе мы боевой отряд, {name}. А порознь -- просто шумные."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "Плечом к плечу, {name}. Кто первым бросится в бой, тот ставит грог."
L["Nobody gets left behind, {name}. I've counted us twice."] = "Никого не бросаем, {name}. Всех пересчитали. Дважды."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "Спасибо, {name}. Добрые сердца есть на любой стороне. И, как видно, здесь."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "Спасибо, {name}. Ни стороны, ни титула, одна доброта. Так начинаются легенды."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "Спасибо, {name}. У доброты нет фракции -- и очень кстати, у меня ее тоже нет."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "Спасибо, {name}. Какой стороне ты достанешься, той крупно повезет."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "Кто бы меня в итоге ни заполучил, {name}, тебя я вспомню первым делом. Спасибо."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "Нейтралитет -- строгий, {name}, но благодарность не в счет. Спасибо."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "С радостью, {name}, каким бы ни было твое знамя. У меня и знамени нет."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "Конечно, {name}. Помогать всем -- единственное, что уже решено."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "Все спрашивают, на чьей я стороне, {name}. Просьба о помощи куда приятнее."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "Конечно, {name}. Военного совета нет, есть только я. И я говорю «да»."
L["Here you are, {name}. No oath, no colours, no fee."] = "Держи, {name}. Без клятв, без знамен, без платы."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "Друзья найдутся на любой стороне, {name}. А то и, как я, ни на какой."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "Скоро нам выдадут гербовые накидки, {name}. А пока присматриваем друг за другом."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "Сторона пока не выбрана, {name}, так что доброты хватит на обе. Держи."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "Подарок без обязательств, {name}. У меня их даже перед фракцией нет."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "Вперед, {name}. Целых две фракции ждут, чтобы поспорить за нас."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "Интенданта пока нет, {name}, так что никто не считает. Бери побольше."
L["Side by side, {name}, whatever comes."] = "Плечом к плечу, {name}, что бы ни случилось."
L["No flag over this party, {name}, just us. That's plenty."] = "Над нашей группой нет флага, {name}, только мы. И этого хватит."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "Однажды мы выберем сторону, {name}. А сегодня -- с кем подраться. Вместе."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "На чьей бы стороне ни был весь мир, {name}, я -- на стороне этой группы."
L["Neutral in the war, {name}, but very partial to this group."] = "В войне -- нейтралитет, {name}. К этой группе -- пристрастие."
L["One good turn deserves another, {name}."] = "Добро за добро, {name}."
L["Have some {buff} in return, {name}."] = "Держи в ответ: {buff}, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "Доброта должна быть взаимной, {name}. Спасибо."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "Твой ход был первым, {name}, мой -- вторым. Назовем это дружбой."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "Спеть бы тебе, {name}, но заклинание {buff} фальшивит меньше."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "Дар за дар, {name}. Так к ужину нас будет не остановить."
L["All square, {name}. Unless you'd like to make it best of three."] = "Мы квиты, {name}. Или играем до двух побед из трех?"
L["You started it, {name}. I'm only finishing it."] = "Кто начал, {name}? Ты. А я только заканчиваю."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "Как мило, {name}. День заметно похорошел. Вот моя половина."
L["You asked, {name}, and here it is."] = "По твоей просьбе, {name}. Держи."
L["{buff}, coming right up, {name}."] = "{buff} -- сейчас будет, {name}."
L["Gladly, {name}. One moment."] = "С радостью, {name}. Минутку."
L["Asked and answered, {name}. Next question?"] = "Спрошено -- отвечено, {name}. Следующий вопрос?"
L["Say the word and it's yours, {name}. You said several. Here."] = "Одно слово -- и это твое, {name}. А слов было несколько. Держи."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "Для тебя, {name}? С радостью. Наконец-то кто-то попросил!"
L["Of course, {name}. Easiest yes I'll say all day."] = "Конечно, {name}. Самое легкое «да» за весь день."
L["Right away, {name}. Finally, a question I know the answer to."] = "Сию минуту, {name}. Наконец-то вопрос, на который я знаю ответ."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "Легкой дороги, {name}. Заклинание {buff} весит меньше меча."
L["A small blessing for the road, {name}."] = "Небольшое благословение в дорогу, {name}."
L["Go well, {name}, and come back in one piece."] = "В добрый путь, {name}, и возвращайся без царапин."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "Без повода, {name}. Просто день сегодня такой: {buff}."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "Я тут мимоходом, {name}. Лишнее завалялось: {buff}."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "Считай это подарком, {name}. Завернуть бы, да сквозь бумагу светится."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "Держи, {name}. Передай дальше, когда встретишь того, кому нужнее."
L["Whatever brings you here, {name}, may it go better than planned."] = "Что бы тебя сюда ни привело, {name}, пусть выйдет лучше задуманного."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "Просто по-соседски, {name}. Соседи мы очень-очень ненадолго."
L["Everyone ready? You are now, {name}."] = "Все готовы? Теперь и ты, {name}."
L["A little something for the party, {name}."] = "Небольшой подарок для группы, {name}."
L["Stay close, {name}. We go further together."] = "Держись рядом, {name}. Вместе мы пройдем дальше."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "Правила дома, {name}: никто не умирает, не дуется, а после -- ужин."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "Вот, {name}. Если что пойдет не так -- уж точно не по моей вине."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "Готово, {name}. Речь бы сказать, да застрянем тут до вечера."
L["Look after that, {name}. It's the only one I brought for you."] = "Береги это, {name}. Для тебя у меня только одно."
L["Now we look the part, {name}. Let's go and be it."] = "Теперь мы похожи на героев, {name}. Пойдем и станем ими."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "Заклинание {buff} у всех свежее, {name}. Дальше -- удача и локти."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "Спасибо, {name}. Сотворить бы тебе подарок, да выйдет опять вода."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "Большое спасибо, {name}. Позже распишу все как следует. Страниц на несколько."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "Спасибо, {name}. В Даларане благодарности не учат. Я самоучка."
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "Как любезно, {name}. Прямо в голову ударило. Но голова -- моя работа."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "Конечно, {name}. И да, воду тебе, видимо, тоже?"
L["As requested, {name}. Side effects may include footnotes."] = "Как заказывали, {name}. Побочные эффекты: возможны сноски."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "Сию минуту, {name}. И аккуратно: на счету моего Скачка сегодня уже две стены."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "С радостью, {name}. Знаниями надо делиться. Так говорит Кирин-Тор. Неохотно."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "Держи, {name}. Завалялась лишняя мысль, а девать ее некуда."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "Держи, {name}. Добавить бы и хлеба, но у сотворенного хлеба нет вкуса."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff} -- тебе, {name}. Бесплатно, не то что порталы."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "Держи, {name}. Обычно те, на кого я указываю, становятся овцами. Тебе сегодня везет."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "Ничего не горит, ничего не замерзло, {name}. Расширяю репертуар."
L["Now that you're clever, {name}, stand between me and the angry things."] = "Раз уж ума прибавилось, {name}, встань между мной и злыми тварями."
L["For the record, {name}, I only blink away when it's tactically sound."] = "Для протокола, {name}: Скачок назад -- только когда это тактически оправдано."
L["There, {name}. Wiser already: look, you're standing further from me."] = "Вот, {name}. Уже мудрее: смотри, ты стоишь дальше от меня."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "Умы заточены, {name}. Огонь, лед и панику беру на себя."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "Как заботливо, {name}. Свет ведет счет, а я плачу по счетам заранее."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "Спасибо, {name}. Замолвлю за тебя словечко перед Светом. Он мне кое-чем обязан."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "Спасибо, {name}. Маленькое чудо, и даже молиться не пришлось."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "Спасибо, {name}. Моя вера в людей восстановлена. Она просто отдыхала."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "Конечно, {name}. У Света нет выходных. У меня, увы, тоже."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "Сию минуту, {name}. Обычно молитвы идут дольше. У тебя, видно, короткий путь."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "Разумеется, {name}. Свет сияет тем, кто просит. Я лишь навожу прицел."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "С удовольствием, {name}. Вера двигает горы, а я начну с малого."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "Здоровья тебе, {name}! Нет, никто не чихал. Это я для верности."
L["Here, {name}. Think of it as a prayer that arrived early."] = "Держи, {name}. Считай это молитвой, услышанной заранее."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "Свет просил тебе передать, {name}. Пересказываю своими словами."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "Держи, {name}. Это избавит нас от неловкого воскрешения потом."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "Даром, {name}. Вера бесплатна. А вот мантия, увы, нет."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "Твоя очередь, {name}. И умоляю всех: сделайте мою работу скучной."
L["Everyone stay near me, {name}. The Light has a limited range."] = "Все держитесь рядом, {name}. У Света ограниченный радиус."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "Готово, {name}. Если кто-то упадет, я очень расстроюсь, а потом все исправлю."
L["Done, {name}. I'll be at the back, praying loudly."] = "Сделано, {name}. Я буду сзади, громко молиться."
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "Спасибо, {name}. Помурлыкать бы, да облик сейчас не тот."
L["Thanks, {name}. My bear form sends a grateful grunt."] = "Спасибо, {name}. Облик медведя шлет благодарное ворчание."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "Большое спасибо, {name}. Облик кошки хочет принести тебе кролика. Я против."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "Спасибо, {name}. Посажу дерево в твою честь. Дай ему лет сто."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "Конечно, {name}. Секунду, вспомню, в каком облике есть руки."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "Конечно, {name}. Замри, как древень. Древни в этом мастера."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "С радостью, {name}. Дикая природа делится всем. Ну, кроме медведей."
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "Сию минуту, {name}. Прости за перья: я прямиком из облика совуха."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "Только что из Изумрудного Сна, {name}. Прости, если зевну."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "Держи, {name}. Природа дарит, а я сегодня у нее на посылках."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "Теперь ты друг дикой природы, {name}. Удобно, ведь у большей ее части есть зубы."
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "Для тебя были и цветы, {name}, но в облике оленя их пришлось съесть. Прости."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "Держи, {name}. Кенарий хотел бы, чтобы это было у тебя. Почти наверняка."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "Ну что, {name}? Что бы ни случилось, медведя не пугать."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "Готово, {name}. Я буду кошкой, медведем, а если придется плыть -- тюленем."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "У меня одно Возрождение, {name}. Не заставляйте меня выбирать."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "Сомкнуть ряды, {name}. Лес смотрит и болеет за нас всеми корнями."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "Доброта, {name}? Любимая добродетель. Чуть выше полировки доспехов."
L["For that, {name}, my best blessing. Not the second best. The best."] = "За это, {name}, мое лучшее благословение. Не второе по качеству. Лучшее."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "Добродетель вознаграждена на месте, {name}! Обожаю, когда так бывает."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "Спасибо, {name}. Клятва велит отвечать добром на добро. Но это и без клятвы."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "Во имя Света, {name}, конечно! Так и хотелось, чтобы кто-нибудь попросил."
L["You have my blessing, {name}. Literally, this time."] = "Мое благословение с тобой, {name}. На этот раз буквально."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "Разумеется, {name}. Можешь преклонить колено. Не настаиваю. Но буду в восторге."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "С радостью, {name}. Благословения у меня не кончаются. Мана -- бывает."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "Свет ничего не просит взамен, {name}. А вот я благодарность принимаю."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "Ступай со Светом, {name}. Я буду прямо за тобой. Лязгая."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "Благословение бесплатно, {name}. От проповеди на этот раз избавлю."
L["There, {name}. It won't last forever, so be heroic while it does."] = "Вот, {name}. Это не навсегда, так что геройствуй, пока действует."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "Выше голову, {name}. Свет идет рядом, а у него отличная осанка."
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "Благословение на тебе, {name}. Уйду потом в бабл -- это чистая тактика."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "Держись, {name}. С нами Свет, а у меня очень большой молот."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "Каждому по благословению, {name}. Свет щедр, но любит очередь."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "Прекрасно, {name}. А теперь на меня не смотреть. Сияю сегодня особенно ярко."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "Как мило, {name}. Мой бес тоже говорит спасибо. Он врет, а я -- нет."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "Спасибо, {name}. Мне сто лет не дарили ничего непроклятого."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "Спасибо, {name}. Отплачу чем-нибудь не из склепа."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "Весьма любезно, {name}. Демону Бездны велено больше над тобой не нависать."
L["Of course, {name}. No soul required. This time."] = "Конечно, {name}. Душа не требуется. На этот раз."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "Просить помощи у чернокнижника, {name}? Смело. Ты мне уже нравишься."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "Конечно, {name}. Бес вызывался помочь, но ему отказано. Ради всех нас."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "Разумеется, {name}. Из всех моих заклинаний только это можно показывать в гостях."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "Держи, {name}. Не спрашивай, откуда. Правда, не надо."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "Упадешь однажды в озеро, {name}, -- вспомнишь меня добрым словом."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "Дыши спокойно, {name}. Обидно было бы потерять тебя из-за такой скукоты, как вода."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "Держи, {name}. Тебе бы еще камень души, но это отдельный разговор."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "Держи, {name}. Единственное мое заклинание, которое одобряют жрецы."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "Все готовы, {name}? Души на месте? Отлично. Пусть так и остается."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "Держись рядом, {name}. Удары берет демон Бездны, а славу -- я."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "Плавай сколько хочешь, {name}. Кого унесет течением -- призову обратно."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "Погладь охотника Скверны, {name}. Только сперва сними заклинания."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "Спасибо, {name}! Ой, громко? У меня одна громкость."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "Большое спасибо, {name}. Заклинаний в ответ нет, зато крик -- очень искренний."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "Спасибо, {name}. Ярости теперь вдвое больше. В хорошем смысле."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "Спасибо, {name}. Твое место -- прямо за мной. Самое безопасное."
L["You want a shout, {name}? I was going to shout anyway."] = "Нужен крик, {name}? Так я и без того ору."
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "Конечно, {name}. Закрой уши: по-другому не умею."
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "Сию минуту, {name}. Будь в пределах слышимости. У меня это далеко."
L["Happily, {name}! Words aren't my strength. Volume is."] = "С радостью, {name}! Слова -- не мой конек. Громкость -- да."
L["Consider yourself shouted at, {name}. Affectionately."] = "Считай, что на тебя наорали, {name}. С любовью."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "Ни благовоний, ни молитв, {name}. Только я и ободряющий крик."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "Выше нос, {name}! Кто будет приставать -- на того Рывок."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "Вот так, {name}! Кто не стал храбрее -- тот просто не слушал."
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "Держи, {name}, немного храбрости. Воины делают ее криком. Как -- не спрашивай."
L["Listen up, {name}! That's it. That was the whole speech."] = "Слушай сюда, {name}! Все. Это была вся речь."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "Где опасность, {name}? Неважно, найду. Лицом вперед."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "Итак, {name}! Иду впереди, ору громче всех, и лекаря никто не трогает."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "Все разозлились? Отлично. Вперед, {name}, и не попадите под мой замах."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "Острый ум тебе, {name}. Мне мой стоил брови в Даларане."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "Больше маны тебе, {name}. Постарайся не спустить все на один огненный шар."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "Мысли гудят, {name}? Это нормально. Если начнут подпевать -- зови."
L["A little arcane for your thoughts, {name}. Keep the change."] = "Немного тайной магии за твои мысли, {name}. Сдачи не надо."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "Гениальность в бутылке, {name}. Кирин-Тор взял бы с тебя еще и за бутылку."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "Острота ума, {name}. Трать на заклинания, замки или загадки -- не осужу."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "Стойкость, {name}: вежливое жреческое «стой впереди»."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "Каждая крупица выносливости -- минус одна моя паническая молитва, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "Ты уже крепче, {name}. Только не воспринимай это как вызов."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "Есть и другие Слова силы, {name}: «Щит», а на крайний случай -- «Беги»."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "Теперь ты покрепче, {name}. Падения, медведи и плохие решения бьют чуть слабее."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. Столько слов там, где хватило бы «будь крепче»."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "Считай, что дух поднят, {name}. Божественно, между прочим."
L["Like a good night's sleep, {name}, without all the lying down."] = "Как крепкий сон, {name}, только без лежания."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "Добавка духа, {name}. Свет всегда настаивает на добавке."
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "Держи дух при себе, {name}. У целителей душ и так работы хватает."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "Защита от тьмы, {name}. Ее фокусы мне знакомы: парочку беру взаймы."
L["Should the Void call, {name}, you can now pretend you're out."] = "Если позовет Бездна, {name}, притворись, что никого нет дома."
L["For when the dark gets personal, {name}. It usually does."] = "На случай, если тьма перейдет на личности, {name}. А она перейдет."
L["The shadows will have to knock first now, {name}."] = "Теперь теням придется сначала постучаться, {name}."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "Знак дикой природы на тебе, {name}. Олени будут приподнимать перед тобой рога."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "От тебя может слегка пахнуть мхом, {name}. Значит, работает."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "Знак дикой природы, {name}. Волки все равно укусят, но им будет стыдно."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "Печать одобрения от самой дикой природы, {name}. С белками согласовано."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "Теперь в тебе есть немного дикости, {name}. Не поддавайся желанию завыть."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "Шкура, когти и густой мех, {name}. Природа пакует скромно, но основательно."
L["Anything that bites you now gets a mouthful, {name}."] = "Кто тебя теперь укусит, получит полный рот колючек, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "Пусть кабан бросается, {name}. Уйдет с сожалениями и занозами."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "Как роза, {name}: любоваться можно, хватать -- ошибка."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "Шипы, {name}. Собственного выращивания, так что повежливее с ними."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "Благословение королей, {name}. Ни короны, ни трона, ни налогов."
L["Long may you reign, {name}. For the next while, anyway."] = "Долгого правления, {name}. Ну, на ближайшее время."
L["A little more of everything, {name}. Kings never did settle for less."] = "Всего понемногу больше, {name}. Короли на меньшее не соглашаются."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "Королевское благословение, {name}. Его носили головы и получше моей. И похуже."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "Все характеристики чуть выше, {name}. Короли любят подстраховаться."
L["Crown not included, {name}. Everything else is, a little."] = "Корона в комплект не входит, {name}. Все остальное -- понемногу."
L["Might doesn't make right, {name}, but it does help the argument."] = "Сила -- еще не правота, {name}, но в споре очень помогает."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "Замах покрепче тебе, {name}. Свет любит удар, доведенный до конца."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "Руки сильнее, {name}. Направляй их, пожалуйста, на тех, кто заслужил."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "Благословение могущества, {name}. Удивит тебя. А их -- еще сильнее."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "Бей смело, {name}. Если все получится, Свет припишет заслугу себе."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "Бей сильнее, {name}. Их, в смысле. Не меня. Паладина -- никогда."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "Мудрость тебе, {name}. Немного оставлено и себе. Совсем чуть-чуть."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "Мудрость для твоей маны, {name}. Настоящая все так же приходит через ошибки."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "Мана теперь возвращается сама, {name}, как кошка, которая тебя простила."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "Меньше глотков между боями, {name}. Трактирщики будут безутешны."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "Пей меньше, колдуй больше, {name}. Финансовый совет от самого Света."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "Благословение мудрости, {name}: единственное, что окупается само."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "Благословение тишины, {name}. Монстры забудут, кто виноват."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "Благословение спасения, {name}. Теперь ты -- чужая проблема."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "Спасение, {name}. Не души, заметь. Только шкуры."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "Бей крепко, {name}. Если кто обернется -- делай невинное лицо. Свет так и сделает."
L["The Light will find you easier now, {name}. Try not to squint."] = "Теперь Свету проще тебя найти, {name}. Постарайся не щуриться."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "Свет небес теперь действует на тебя сильнее, {name}. Только не заставляй проверять."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "Тебя теперь легче лечить, {name}. Свет ценит сговорчивых пациентов."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "Благословение света, {name}. Спасать тебя теперь проще. Не то чтобы понадобилось."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "Заблокируй удар, {name}, и Свет ответит за тебя. Он злопамятный."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "Теперь удары мягче, {name}. Жалобы -- к Свету."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "Защита храма, {name}, и никакого ремонта крыши."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "Проси убежища, {name}. Проще, когда носишь его с собой."
L["Instructions, {name}: hit things harder. There is no page two."] = "Инструкция, {name}: бей сильнее. Второй страницы нет."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "С рукой для меча разобрались, {name}. С остальным -- к жрецу."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "Боевой крик, {name}. Не заклинание, а настоятельная рекомендация."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "РРРАААХ! Это было тебе, {name}. Остальные просто подслушали."
L["A little breath from the damned, {name}. They weren't using it."] = "Немного дыхания от проклятых, {name}. Им оно все равно ни к чему."
L["Unending Breath, {name}. The fish will have so many questions."] = "Бесконечное дыхание, {name}. У рыб будет столько вопросов."
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "Сиди под водой сколько хочешь, {name}. Дыхание за тебя задерживает кое-кто другой."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "Ныряй глубже, {name}. Если мурлок спросит -- ты в гостях."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "Со стороны похоже на дуэль, {name}. Спасибо за заклинание {gift}."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} -- мне, {buff} -- тебе. Аукцион отдыхает, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "Опередили, {name}! Заклинание {gift} быстрее моих манер."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "Пришло: {gift}. Ушло: {buff}. Лучшая экономика Азерота."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift} -- мне? Могу ответить только этим, {name}, но от всего сердца."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "Заклинание {gift} как влитое, {name}. Мерки с меня снимали?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "Договор, {name}: с тебя {gift}, с меня {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! Прямо расту на глазах. Держи: {buff}."
L["I was about to ask for {gift}, {name}. You read my mind."] = "Мысли читаешь, {name}? Как раз хотелось попросить: {gift}."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "Заклинание {gift} еще искрится, {name}. Вот тебе ответные искры."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "Славный подарок, {name}: {gift}. Расскажу всей таверне. Дважды."
L["You cast {gift} first, {name}? My mother would despair of me."] = "{gift} от тебя, и раньше моего, {name}? Мама бы во мне разочаровалась."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "{gift} -- это я запомню надолго, {name}. Пока не выветрится."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "Даром: {gift} и {buff}. Где-то плачет один гоблин."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "Твое -- {gift}, мое -- {buff}. Теперь мы невыносимы."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "Спасибо за заклинание {gift}, {name}. Отработаю, пока не развеялось."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "{gift}! За такое и обеих лун не жалко, {name}. Но пока -- вот."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "Твой вклад: {gift}. Мой: {buff}. Вот теперь это вечеринка."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! Мне пришли три умные мысли, {name}. Эта -- одна из них."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "{gift} -- и я наконец понимаю свои записи, {name}. Спасибо."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "Ума прибавилось, {name}. Хватает, чтобы понять: я в долгу. Держи."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? Ради такого разок постою впереди. Недолго."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "Колени, локти и гордость, {name}: все укреплено. Спасибо."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "Ударь меня, {name}. Нет, не надо. Но спасибо: теперь это можно пережить."
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift}! Мой дух поднят, {name}. Похоже, буквально."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "Спокойствия вдвое больше, ворчливости вдвое меньше, {name}. Спасибо."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "Тьма мне теперь нипочем, {name}. Шепоты в бешенстве. Спасибо."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "Теперь ничто темное не пройдет, {name}. А вот тебе кое-что светлое навстречу."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! Мне только что кивнула белка, {name}. А это тебе."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "Шкура толще, нюх острее, {name}. Лишь бы не потянуло в кусты за ягодами."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "Столько дикости и листвы, {name}! Спасибо. Прости, если посыплется кора."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! Сегодня меня никто не обнимет. Держи вместо объятий."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "Колючести прибавилось, {name}, спасибо. Больше обычного, в смысле."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift} от тебя, {name}? Постараюсь не основать династию."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "Во всем чуть лучше, {name}. Так вот каково королям? Неудивительно."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "Руки уже сильнее, {name}. Постараюсь никого не обнимать. Спасибо."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "{gift} -- хоть кодо поднимай, {name}. Не буду, но спасибо."
L["{gift} from you, {name}, and my first wise act is this."] = "{gift} от тебя, {name}, и мой первый мудрый поступок -- вот."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "Мудрости уже хватает, {name}, чтобы узнать доброту с первого взгляда."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! Монстры сразу меня забыли, {name}. А я тебя -- нет."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "Со мной теперь никто не хочет драться, {name}. Прелесть. Спасибо."
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "Свету теперь проще меня найти, {name}. Он говорит спасибо, и я тоже."
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "Меня теперь легче лечить, {name}. Мой лекарь тоже благодарит."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "Удары теперь мягче, {name}. Мои синяки говорят спасибо, и я тоже."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "Каждый удар нежнее, {name}, спасибо. Уж я прослежу, чтобы они заметили."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "На меня накричали, {name}, а на душе бодро как никогда. Держи."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "В ушах звенит, {name}, а руки вдвое сильнее. Спасибо!"
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "Могу дышать под водой, {name}! Может, и не пригодится, но спасибо."
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "Легкие как у мурлока, {name}. Мргл. Прости. Спасибо."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "Надо прекращать так встречаться, {name}. Хотя нет, не надо."
L["Again, {name}? Splendid. I've been practising since last time."] = "Снова, {name}? Прекрасно. С прошлого раза практики прибавилось."
L["You again, {name}? People will start saying we're friends."] = "Опять ты, {name}? Пойдут слухи, что мы друзья."
L["Same face, same spell, {name}. I do love a tradition."] = "То же лицо, то же заклинание, {name}. Обожаю традиции."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "Еще раунд, {name}? Счет веду я, и выигрываем мы вдвоем."
L["Ah, {name}! My favourite repeat customer."] = "А, {name}! Мой любимый постоянный клиент."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "Наши пути все время пересекаются, {name}. Кажется, дорога на что-то намекает."
L["Hello again, {name}. Do stop me if you've heard this one."] = "Снова привет, {name}. Останови меня, если это уже было."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "Кое-что было отложено, {name}, на случай, если вернешься. Чутье не подвело."
L["Back already, {name}? I'm starting to think you like me."] = "Уже снова тут, {name}? Начинаю думать, что я тебе нравлюсь."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, нам пора уже завести общую сумку для реагентов."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "Завтра в то же время, {name}? С меня {buff}. С тебя -- ты."
L["I've lost count, {name}, and I've decided that's a compliment."] = "Счет уже потерян, {name}, и будем считать это комплиментом."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "Продолжим в том же духе, {name}, и барды сложат о нас очень скучную песню."
L["I could do this one in my sleep by now, {name}. I may have."] = "Это уже можно делать во сне, {name}. Возможно, так и было."
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}, как обычно? Конечно, как обычно. Всегда как обычно."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "Нам уже пора придумать тайное рукопожатие, {name}. Может, в следующий раз."
L["By now, {name}, I think we've built a small economy between us."] = "Похоже, {name}, мы уже построили между собой маленькую экономику."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "Мы уже старые друзья, {name}. Ну, старые знакомые с отличным чувством момента."
L["Let the record show: {name} and I, undefeated at being prepared."] = "Занесите в протокол: {name} и я -- непобедимы в готовности."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "Крепкие стены, теплые постели, а теперь и {buff}. Тебя балуют, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "Стража и так начеку, {name}, но я люблю основательность."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "Осторожнее, {name}. С таким бравым видом в городе тебя завалят просьбами."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "На мили вокруг ни одного монстра, {name}. Но за местную кухню не поручусь."
L["For the crowds, {name}. In town, they're the real danger."] = "Это от толпы, {name}. В городе главная опасность -- она."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "Отдыхай спокойно, {name}. Засчитаю себе доброе дело и пойду за кружкой."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "Даже в город, {name}, бывало, залетали драконы. Лучше перестраховаться."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "Лучше здесь, {name}. Снаружи никто не стоит на месте достаточно долго."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "Здесь все хочет тебя съесть, {name}. Теперь понадобится вилка побольше."
L["No guards for miles, {name}, and the boars know it. Take this."] = "Стражи тут нет и в помине, {name}, и кабаны это знают. Держи."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "Здесь только мы и звери, {name}. Давай будем той половиной, что покрепче."
L["If a bear asks, {name}, you were like this when I found you."] = "Если медведь спросит, {name}: так и было."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "Волки давно на тебя поглядывают, {name}. Это их слегка остудит."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "Дикие края, {name}. Одними добрыми намерениями тут не обойтись."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "Карта, фляга, {buff}. Теперь можно заблудиться как следует, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "До лагеря далеко, {name}. Считай это крышей, которую носят с собой."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "Где-то тут злодей репетирует речь, {name}. Давай его перебьем."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "Что бы ни ждало в конце, {name}, пусть пожалеет."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "Говорят, отсюда никто не уходит живым, {name}. Давай невежливо докажем обратное."
L["Our host had years to prepare, {name}. We have {buff}."] = "У хозяина были годы на подготовку, {name}. У нас -- {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "Подземелья не строят с черным ходом, {name}. Держи это вместо него."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "Темные залы, старые ловушки, скверные нравы. Зато ты во всеоружии, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "Лучше вручить тебе это сейчас, {name}, чем надгробную речь потом."
L["There's treasure in here, {name}, and something very large sat on it."] = "Тут есть сокровища, {name}, и на них сидит что-то очень большое."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "Флаги, башни, кладбища, {name}. За что бы мы ни дрались -- держи."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "Победим или нет, {name}, но без подготовки тебя не оставили."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "Кладбище вон там, {name}. Давай не будем туда заглядывать."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "На кону честь, {name}. И флаг. В основном флаг."
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "Держись группы, {name}. Герои-одиночки попадают в песни другой стороны."
L["Early bird, {name}? Here's something better than a worm."] = "Ранняя пташка, {name}? Держи кое-что получше червячка."
L["Good morning, {name}. Consider this your first cup of something strong."] = "Доброе утро, {name}. Считай это первой чашкой чего-нибудь крепкого."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "Ранний старт, {name}. День еще не успел пойти наперекосяк."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "Еще даже не обед, {name}, а подготовка у тебя уже лучше моей."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "С утра пораньше, {name}. Где-то монстры еще зевают."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "Новый день, свежее заклинание {buff}, {name}. Не упустим ни то, ни другое."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "Гуляешь так поздно, {name}? Ночь голоднее дня. Держи."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "Пора бы спать, {name}. Все благоразумные уже спят, остались только мы."
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "Тоже не спится, {name}? Тогда будем хорошо защищенными полуночниками."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "Остерегайся темноты, {name}. Не все там такие же дружелюбные, как я."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "Поздно, {name}. Этого хватит, пока солнце о нас не вспомнит."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "Не спят только совы да мы, {name}. Но {buff} -- не для сов."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "Рыбак рыбака видит издалека, {name}. И помогает как следует."
L["From one of our trade to another, {name}. No need to check my work."] = "От коллеги коллеге, {name}. За мной можно не проверять."
L["Professional courtesy, {name}. We don't charge each other."] = "Профессиональная любезность, {name}. Со своих не берем."
L["Two of a kind, {name}. Between us we could write the manual."] = "Мы с тобой одной породы, {name}. Вдвоем хоть учебник пиши."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "Не удивляйся так, {name}. Наверное, у нас один наставник."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "Покритиковать бы твою технику, {name}, да моя точно такая же."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "Только другим не говори, {name}, но наше призвание -- лучшее."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "Посмотри на нас, {name}: со стороны все так легко. А ведь нелегко, правда?"
L["I'd shout some encouragement, {name}, but you do that far better."] = "Крикнуть бы тебе что-то ободряющее, {name}, да у тебя это выходит лучше."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "Бросайся в бой как обычно, {name}. Просто мне теперь будет спокойнее."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "Тому, кто идет первым, {name}. Кто-то же должен, и это никогда не я."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "Ты принимаешь удары за всех нас, {name}. Это меньшее, что я могу сделать."
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "Давай, {name}, в атаку. Я прямо за тобой. Довольно далеко за тобой."
L["Save the bubble for later, {name}. This one's from me."] = "Прибереги бабл на потом, {name}. А это от меня."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "Ты весь день благословляешь других, {name}. Вот одно и в твою сторону."
L["The Light already likes you, {name}. Consider this a second opinion."] = "Свет тебя и так любит, {name}. Считай это вторым мнением."
L["Even the Light's own champion needs a hand now and then, {name}."] = "Даже поборнику Света иногда нужна помощь, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "Попросить бы благословение в ответ, {name}, но так мы тут до вечера простоим."
L["One for you, {name}, and a pat on the head for your companion."] = "Это тебе, {name}, а твоему питомцу -- почесать за ухом."
L["You watch everyone's back from range, {name}. I've got yours."] = "Ты издалека прикрываешь всем спины, {name}. Твою прикрою я."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "Им -- Метка охотника, тебе -- {buff}, {name}. Так гораздо приятнее."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "Целься точнее, {name}. А если оно все равно бросится на тебя -- беги к нам."
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "Твой питомец смотрел на меня с надеждой, {name}. Это тебе, а ему передай извинения."
L["For the one I never see coming, {name}. Meant as the highest praise."] = "Тому, кто всегда появляется неожиданно, {name}. Это высшая похвала."
L["Quick, {name}, before you vanish again."] = "Скорее, {name}, пока тебя и след не простыл."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "Яд на клинках, {buff} -- на тебе. Очень основательно, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "Подложить бы тебе это в карман, {name}, но ты заметишь. Ты всегда замечаешь."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "Тому, кто вскрывает любые замки, {name}. Этот подарок -- без замка."
L["For once, {name}, somebody's looking after the priest."] = "Хоть раз, {name}, кто-то позаботится о жреце."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "Прибереги молитвы для остальных, {name}. Эта уже услышана."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "Свет или Тьма, {name}? Не спрашиваю. Подходит к обоим."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "После этого боя присядь, {name}. Это приказ благодарного пациента."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "Ты держишь нас всех на ногах, {name}. Вот немного обратно."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "К этому не прилагается голос в голове, {name}. Непривычно, правда?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "Черный Клинок одолжений не просит, {name}. А я все равно сделаю."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "Немного тепла, {name}. Знаю, холода ты не чувствуешь. Важно внимание."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "Смерть тебя уже однажды отпустила, {name}. Помогу, чтобы не передумала."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "Руны, чума и лед, {name}. Возьми и это -- для полного комплекта."
L["The elements look after you, {name}, but they don't make house calls."] = "Стихии заботятся о тебе, {name}, но на дом не приходят."
L["Tell the spirits I said hello, {name}. They never write back."] = "Передай духам привет, {name}. Мне они никогда не отвечают."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "Поставь тотем в мою честь, {name}. Маленький. Из скромности."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "Земля, огонь, вода, воздух и я, {name}. Признаю, скромнейшая из пяти стихий."
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "Тотемы уже стоят, {name}? Тогда это -- рядом с ними. Только не закапывай."
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "Подарок магу, {name}? Все равно что носить воду... ну, тебе."
L["You solve most problems with sheep, {name}. This covers the rest."] = "Большинство проблем ты решаешь овцами, {name}. Это -- для остальных."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "Ты можешь телепортироваться из любой передряги, {name}. А это -- чтобы до нее дожить."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "Для умной головы, {name}. Только не благодари превращением в овцу."
L["Blink wherever you like, {name}. This comes too."] = "Скачи куда хочешь, {name}. Это прискачет с тобой."
L["Entirely demon-free, {name}. I checked."] = "Ни одного демона внутри, {name}. Проверено."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "Твой бес может приревновать, {name}. Скажи ему, что на всех хватит."
L["No contract, no fine print, {name}. Just a gift."] = "Без контракта и мелкого шрифта, {name}. Просто подарок."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "Тому, кто раздает камни здоровья, {name}. Тебя ведь никто не благодарит."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "Держи, {name}. Призовешь нас потом -- и будем в расчете."
L["Roll wherever you like, {name}. This rolls with you."] = "Кувыркайся куда угодно, {name}. Это кувыркнется следом."
L["Brew first or fight first, {name}? Either way, take this."] = "Сначала хмель или сначала бой, {name}? Так или иначе, держи."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "Тебе внутренний покой, {name}, и внешний тоже -- пока действует."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "С небольшой помощью ци течет лучше, {name}. Так мне говорил один монах."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "Удар, сальто, кувырок, {name}. А я просто постою тут и сделаю вот это."
L["Tell the bear this is for them too, {name}."] = "Передай медведю, что это и для него, {name}."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "Замри, {name}. В облике гепарда тебя ни разу не удалось догнать."
L["Nature looks after you already, {name}. Today she sent me to help."] = "Природа и так о тебе заботится, {name}. Сегодня она прислала меня."
L["Whatever shape you're in next, {name}, this goes with you."] = "Какой облик ни примешь, {name}, это останется с тобой."
L["For the forest's friend, {name}. Give my regards to the trees."] = "Другу леса, {name}. Передавай привет деревьям."
L["You were not prepared, {name}. Now you are."] = "«Вы не готовы!» Теперь готовы, {name}."
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "Десять тысяч лет в темнице, {name}. Немного доброты тебе положено."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "Битва с Легионом стоила тебе так многого, {name}. Вот немного обратно."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "Тому, кто прыгает первым, {name}. Приземляйся где-нибудь поприятнее."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "Скверна и ярость, {name}, а теперь немного доброты. Для баланса."
L["For you, {name}. Please don't breathe on it."] = "Это тебе, {name}. Только не дыши на него огнем."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "Немного помощи дракону, {name}. Буду рассказывать внукам."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "Аспекты отправили тебя в мир, {name}. А я делаю его дружелюбнее."
L["Take to the skies after this, {name}. I'll wave from down here."] = "После этого -- в небо, {name}. А я помашу снизу."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "Дракон на нашей стороне, {name}. Щедрость еще никогда не была так безопасна."
L["{buff} for a mage, {name}. Like lending a library a book."] = "{buff} -- магу, {name}. Все равно что дарить книгу библиотеке."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "Маг магу, {name}: я не прошу у тебя воды, а ты -- у меня."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "Два мага, {name}. Порталом куда угодно -- и все равно опоздаем."
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "Маг для мага, {name}. В Кирин-Торе это назвали бы рецензированием."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "Жрец жрецу, {name}: кто благословит благословляющих? Сегодня -- я."
L["Between us priests, {name}, we'll both pretend the tank listens."] = "Между нами, жрецами, {name}: сделаем вид, что танк нас слушает."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "Жрец заботится о жреце, {name}. Прямо что-то запретное."
L["Two priests, {name}. Twice the praying and half the panic."] = "Два жреца, {name}. Вдвое больше молитв и вдвое меньше паники."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "Два друида, {name}. Круг Кенария назвал бы это кворумом."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "Друид друиду, {name}: медведем или кошкой -- узнаю тебя по листьям в волосах."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "Оборотень оборотню, {name}: это подходит к любому облику."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "Без рукопожатия, {name}. Два друида, и ни у одного нет подходящего облика."
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "Паладин паладину, {name}: я молчу про бабл, если ты молчишь."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "Благословение паладину, {name}. Теперь мы сияем вдвоем. Невыносимо."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "Два паладина, {name}. Где-то с облегчением выдохнул жрец."
L["One of us should be humble about this, {name}. Neither of us will be."] = "Кому-то из нас стоило бы проявить скромность, {name}. Никто не проявит."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "Чернокнижник чернокнижнику, {name}: держи беса подальше от моего. Сплетничают."
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "Коллега-чернокнижник, {name}? Тогда ты знаешь: это правда безвредно. Честно."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "Два чернокнижника, {name}. Не будем мериться осколками души на людях."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "Между нами, {name}, всю работу делают демоны. А это -- собственноручно."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "Два воина, {name}. Где-то тяжело вздохнул лекарь."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "Воин воину, {name}: кто первым в бой, тот и угощает. Угощаю я."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "Крик за крик, {name}. Вместе оглушим всю округу."
L["No plan, {name}? Perfect. We'll get along."] = "Нет плана, {name}? Отлично. Мы поладим."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "Ага, {name}, стоило лишь попросить! Не дергайся!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "На-ка, {name}, чуток подмоги, чтоб ноги держали."
L["My thanks, {name}. Allow me to return the kindness."] = "Благодарю, {name}. Позволь ответить тем же."
L["Of course, {name}. Stand fast a moment."] = "Конечно, {name}. Замри на мгновение."
L["The road ahead is long, {name}. Take this with you."] = "Впереди долгий путь, {name}. Возьми это с собой."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ишну-ала, {name}. Добро возвращается к тебе."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Элун-адоре, {name}. Ступай легко под звездами."
L["The Light rewards kindness, {name}, and so shall I."] = "Свет воздает за доброту, {name}, и я тоже."
L["Of course, {name}. May the Naaru guide your steps."] = "Конечно, {name}. Да направят наару твои шаги."
L["The Light is with you, {name}. Go in peace."] = "Свет с тобой, {name}. Иди с миром."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Премного благодарю, {name}. Гилнеас добра не забывает."
L["Lok'tar ogar, {name}! Take this into battle."] = "Лок'тар огар, {name}! Возьми это в бой."
L["The Earth Mother sees your kindness, {name}. I return it."] = "Мать-Земля видит твою доброту, {name}. Отвечаю тем же."
L["Of course, {name}. Stand tall and be at peace."] = "Конечно, {name}. Стой гордо, и мир тебе."
L["Walk with the Earth Mother, {name}."] = "Ступай с Матерью-Землей, {name}."
L["Sure ting, {name}. Hold still now."] = "Без проблем, {name}. Стой смирно, мон."
L["Da loa be watchin' over ya, {name}."] = "Лоа за тобой приглядывают, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Такая учтивость делает тебе честь, {name}. Анар'ала белорэ."
L["Anar'alah belore, {name}. May the sun guide you."] = "Анар'ала белорэ, {name}. Да ведет тебя солнце."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Твоя щедрость не забыта, {name}. Сурамар помнит своих друзей."
L["Thank you, {name}! The caravan always repays a kindness."] = "Спасибо, {name}! Караван всегда отвечает на доброту."
L["Every traveller needs something for the road, {name}."] = "Каждому путнику нужно что-то в дорогу, {name}."
L["Of course, {name}. Patience, and it is done."] = "Конечно, {name}. Немного терпения, и готово."
L["Take this, {name}. Even a dragon needs allies."] = "Держи, {name}. Даже дракону нужны союзники."
L["Thank you, {name}. The Alliance looks after its own."] = "Спасибо, {name}. Альянс своих не бросает."
L["Of course, {name}. Allies help each other."] = "Конечно, {name}. Союзники помогают друг другу."
L["For the Alliance, {name}! Stay strong out there."] = "За Альянс, {name}! Не теряй силы духа."
L["Strength and honour, {name}. Your kindness is repaid."] = "Сила и честь, {name}. Твоя доброта вознаграждена."
L["Consider it done, {name}. For the Horde."] = "Будет сделано, {name}. За Орду."
L["For the Horde, {name}! Go with strength."] = "За Орду, {name}! Да пребудет с тобой сила."
L["Thank you, {name}. Good hearts are found everywhere."] = "Спасибо, {name}. Добрые сердца есть везде."
